const root=document.querySelector('#prazos-view'),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),dt=v=>v?v.split('-').reverse().join('/'):'—',today=()=>new Date().toISOString().slice(0,10);let orders=[];const effective=r=>r.newDate||r.deliveryDate,statuses=['Aguardando entrega','Entregue','Cancelado'];root.innerHTML=`<div class="deadline-kpis"></div><section class="panel"><h3>Novo / editar pedido</h3><form data-form><div class="cement-fields"><label>Código<input name="code" required></label><label>Produto<input name="product" required></label><label>Pedido de compra<input name="purchaseOrder" required></label><label>Contato<input name="contact"></label><label>Fornecedor<input name="supplier" required></label><label>Status<select name="status">${statuses.map(x=>'<option>'+x+'</option>').join('')}</select></label><label>Data entrega prevista<input name="deliveryDate" type="date" required></label><label>Quantidade<input name="quantity" required></label><label>Frete<input name="freight"></label><label>UN<input name="unit" required placeholder="KG, UN, MIL..."></label><label>Nova data<input name="newDate" type="date"></label><label class="cement-notes">Observação<textarea name="notes" rows="2"></textarea></label></div><button type="submit">Salvar pedido</button> <button type="button" data-cancel hidden>Cancelar edição</button><p class="cement-message"></p></form></section><section class="panel"><h3>Controle dos prazos</h3><div class="cement-filters"><label>Fornecedor<input data-supplier type="search" placeholder="Todos"></label><label>Status<select data-status><option value="">Todos</option>${statuses.map(x=>'<option>'+x+'</option>').join('')}</select></label><label>Buscar<input data-search type="search" placeholder="Código, produto ou pedido"></label></div><div class="deadline-table"></div></section>`;const form=root.querySelector('[data-form]'),msg=root.querySelector('.cement-message');root.querySelectorAll('[data-supplier],[data-status],[data-search]').forEach(x=>x.oninput=render);function cls(r){if(r.status==='Entregue')return'deadline-delivered';if(r.status==='Cancelado')return'';const d=effective(r),t=today();if(d<t)return'deadline-late';const soon=new Date();soon.setDate(soon.getDate()+7);return d<=soon.toISOString().slice(0,10)?'deadline-soon':''}function render(){const t=today(),late=orders.filter(r=>r.status==='Aguardando entrega'&&effective(r)<t).length,soon=orders.filter(r=>{const e=effective(r),d=new Date();d.setDate(d.getDate()+7);return r.status==='Aguardando entrega'&&e>=t&&e<=d.toISOString().slice(0,10)}).length,waiting=orders.filter(r=>r.status==='Aguardando entrega').length,done=orders.filter(r=>r.status==='Entregue').length;root.querySelector('.deadline-kpis').innerHTML=`<div><strong>${late}</strong><span>Atrasados</span></div><div><strong>${soon}</strong><span>Próximos 7 dias</span></div><div><strong>${waiting}</strong><span>Aguardando entrega</span></div><div><strong>${done}</strong><span>Entregues</span></div>`;const q=root.querySelector('[data-search]').value.toLowerCase(),sup=root.querySelector('[data-supplier]').value.toLowerCase(),st=root.querySelector('[data-status]').value,rows=orders.filter(r=>(!sup||r.supplier.toLowerCase().includes(sup))&&(!st||r.status===st)&&(!q||(r.code+' '+r.product+' '+r.purchaseOrder).toLowerCase().includes(q))).sort((a,b)=>effective(a).localeCompare(effective(b)));root.querySelector('.deadline-table').innerHTML=rows.length?'<div class="table-scroll"><table><thead><tr><th>Cód</th><th>Produto</th><th>Pedido</th><th>Contato</th><th>Fornecedor</th><th>Status</th><th>Entrega prevista</th><th>Qtde</th><th>Frete</th><th>UN</th><th>Nova data</th><th>Observação</th><th></th></tr></thead><tbody>'+rows.map(r=>'<tr class="'+cls(r)+'"><td>'+esc(r.code)+'</td><td>'+esc(r.product)+'</td><td>'+esc(r.purchaseOrder)+'</td><td>'+esc(r.contact||'—')+'</td><td>'+esc(r.supplier)+'</td><td>'+esc(r.status)+'</td><td>'+dt(r.deliveryDate)+'</td><td>'+esc(r.quantity)+'</td><td>'+esc(r.freight||'—')+'</td><td>'+esc(r.unit)+'</td><td>'+dt(r.newDate)+'</td><td>'+esc(r.notes||'—')+'</td><td><button data-edit="'+r.id+'">Editar</button></td></tr>').join('')+'</tbody></table></div>':'<p class="empty-state">Nenhum pedido cadastrado.</p>';root.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(b.dataset.edit))}function reset(){form.reset();form.elements.status.value='Aguardando entrega';delete form.dataset.id;delete form.dataset.version;root.querySelector('[data-cancel]').hidden=true}function edit(id){const r=orders.find(x=>x.id===id);for(const[k,v]of Object.entries(r))if(form.elements[k])form.elements[k].value=v;form.dataset.id=r.id;form.dataset.version=r.version;root.querySelector('[data-cancel]').hidden=false;form.scrollIntoView({behavior:'smooth'})}root.querySelector('[data-cancel]').onclick=reset;form.onsubmit=async e=>{e.preventDefault();const input=Object.fromEntries(new FormData(form));if(form.dataset.id){input.id=form.dataset.id;input.version=Number(form.dataset.version)}try{const r=await fetch('/api/deadlines',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)}),j=await r.json();if(!r.ok)throw Error(j.error);reset();msg.textContent='Pedido salvo.';await refresh()}catch(e){msg.textContent=e.message}};async function refresh(){const r=await fetch('/api/deadlines'),j=await r.json();if(!r.ok)throw Error(j.error);orders=j.orders||[];render()}reset();refresh().catch(e=>msg.textContent=e.message);